def is_samepatterns(patterns: list[str], values: list[str]) -> bool:
    """
    Check whether the values list follows the pattern given by patterns.

    Args:
        patterns: The pattern list with placeholder strings like 'a', 'b', etc.
        values: The actual values to check against the pattern.

    Returns:
        True if values follows the patterns, False otherwise.
    """
    mapping: dict[str, str] = {}
    seen_values: dict[str, str] = {}

    for p, v in zip(patterns, values):
        if p in mapping:
            if mapping[p] != v:
                return False
        else:
            mapping[p] = v
            if v in seen_values:
                # Same value should map to the same pattern character
                if seen_values[v] != p:
                    return False
            seen_values[v] = p

    return True
```

