def find_dissimilar(t1: tuple, t2: tuple) -> tuple:
    """Find elements that appear in only one of the two tuples (symmetric difference)."""
    set1 = set(t1)
    set2 = set(t2)
    result = []
    for x in t1:
        if x not in set2:
            result.append(x)
    for x in t2:
        if x not in set1:
            result.append(x)
    return tuple(result)
```

