def jacobsthal_num(n: int) -> int:
    """Return the nth Jacobsthal number.

    Jacobsthal numbers follow: J(n) = J(n-1) + 2*J(n-2)
    with J(0) = 0, J(1) = 1.
    Sequence: 0, 1, 1, 3, 5, 11, 21, 43, 85, 171, 341, 683, 1365, 2731, ...
    """
    memo = {0: 0, 1: 1}

    def helper(k: int) -> int:
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + 2 * helper(k - 2)
        return memo[k]

    return helper(n)
```

