def remove_nested(t: tuple) -> tuple:
    """Remove all nested tuples from the given tuple and return a flattened tuple."""
    result = []
    for item in t:
        if isinstance(item, tuple):
            result.extend(remove_nested(item))
        else:
            result.append(item)
    return tuple(result)
